function main() {
  const filePath = path.resolve('src/i18n/translations.ts')
  let content = fs.readFileSync(filePath, 'utf8')

  function buildBlock(lang, keys) {
    const lines = []
    for (const [key, translations] of Object.entries(keys)) {
      const value = translations[lang]
      if (value === undefined) {
        throw new Error(`Missing translation for ${key} in ${lang}`)
      }
      lines.push(`      "${key}": "${value}",`)
    }
    return lines.join('\n') + '\n'
  }

  for (const lang of langs) {
    const langBlockRe = new RegExp(`(  ${lang}: \\{[\\s\\S]*?\\n  \\},)`, 'm')
    const match = content.match(langBlockRe)
    if (!match) {
      console.warn(`Language block ${lang} not found`)
      continue
    }
    const block = match[1]
    const newBlock = block.replace(new RegExp('\\n    \\},\\n  \\},'), `\\n${buildBlock(lang, missingKeys)}    },\\n  },`)
    content = content.replace(block, newBlock)
  }

  fs.writeFileSync(filePath, content)
  console.log(`Injected ${Object.keys(missingKeys).length} keys into ${langs.length} languages`)
}

main()
